(function(){angular.module("app.quick-panel").controller("QuickPanelController",QuickPanelController);function QuickPanelController(msApi){var vm=this;vm.date=new Date();vm.settings={notify:true,cloud:false,retro:true};msApi.request("quickPanel.activities@get",{},function(response){vm.activities=response.data
});msApi.request("quickPanel.events@get",{},function(response){vm.events=response.data});msApi.request("quickPanel.notes@get",{},function(response){vm.notes=response.data})}})();